         if (ret == UA_STATUSCODE_GOOD) {
             // do nothing
         }
         UA_ByteString_deleteMembers(&encoded);
     }
     UA_delete(dst, &UA_TYPES[typeIndex]);

     return UA_TRUE;
 }

